-- M07 fixed-source metadata/data readback. No Auth rows, key values, credential digests, secrets or private payloads.
begin isolation level repeatable read read only;set local search_path='';set local timezone='UTC';set local statement_timeout='30s';
-- Transcript28 read-only projection includes established M06 rows and excludes key columns before SELECT. Never hashes or emits
-- managed Auth bodies, verification keys, bearer digests or replay ciphertext.
do $m06_data$
declare item record;amount bigint;fingerprint text;column_names text;counts jsonb:='{}';hashes jsonb:='{}';new_tables text[]:=array['app_settings','mcp_oauth_resources']::text[];
begin
 for item in select n.nspname,c.relname from pg_class c join pg_namespace n on n.oid=c.relnamespace where c.relkind='r'
 and(n.nspname='eps'and not c.relname=any(new_tables)or n.nspname='public'and c.relname in('clients','projects','project_memberships','client_memberships','app_capability_grants')or n.nspname='storage'and c.relname in('buckets','objects'))order by n.nspname,c.relname loop
  execute format('select count(*)from %I.%I',item.nspname,item.relname)into amount;
  counts:=counts||jsonb_build_object(item.nspname||'.'||item.relname,amount);
  -- Credential columns are absent from the SELECT before serialization.
  select string_agg(format('%I',a.attname),','order by a.attnum)into column_names from pg_attribute a where a.attrelid=format('%I.%I',item.nspname,item.relname)::regclass and a.attnum>0 and not a.attisdropped
   and a.attname!~'(secret|password|token|nonce|ciphertext|encrypted|_digest$|request_mac)'
   and not a.attname=any(array['secret','backend_key','token_digest','session_token_digest','lease_token_digest','response_encrypted','response_ciphertext','encrypted_response','password','key_material']);
  execute format($q$select encode(sha256(convert_to(coalesce(string_agg(safe::text,E'\n'order by safe::text),''),'UTF8')),'hex')from(select to_jsonb(r)as safe from(select %s from %I.%I)r)s$q$,column_names,item.nspname,item.relname)into fingerprint;
  hashes:=hashes||jsonb_build_object(item.nspname||'.'||item.relname,fingerprint);
 end loop;
 perform set_config('eps.m07_readback.old_data',jsonb_build_object('counts',counts,'hashes',hashes,'managed_auth',jsonb_build_object('user_count',(select count(*)from auth.users),'session_count',(select count(*)from auth.sessions),'users_metadata',(select jsonb_build_object('owner',relowner::regrole::text,'rls',relrowsecurity,'force_rls',relforcerowsecurity,'acl',relacl::text)from pg_class where oid='auth.users'::regclass),'sessions_metadata',(select jsonb_build_object('owner',relowner::regrole::text,'rls',relrowsecurity,'force_rls',relforcerowsecurity,'acl',relacl::text)from pg_class where oid='auth.sessions'::regclass)),'versions',(select jsonb_agg(version order by version)from supabase_migrations.schema_migrations))::text,true);
end$m06_data$;

-- Dynamic relation discovery permits an exact reviewed24 preflight. Key bytes
-- are never projected, hashed, serialized or placed in a derived checksum.
do $m06_state$
declare name text;metadata jsonb;tables jsonb:='{}';config jsonb;begin
 foreach name in array array['review_gateway_config','review_gateway_nonces','review_gateway_rates','review_links','review_link_replays','guest_sessions','feedback_comments','feedback_preferences','presentation_exports','review_media_grants','guest_asset_grants','guest_idempotency','presentation_video_transcripts']loop
  if to_regclass('eps.'||name)is null then metadata:=null;else execute format('select jsonb_build_object(''count'',count(*))from eps.%I',name)into metadata;end if;
  tables:=tables||jsonb_build_object(name,metadata);
 end loop;
 if to_regclass('eps.review_gateway_config')is not null then
  execute 'select jsonb_build_object(''enabled'',enabled,''key_present'',backend_key is not null,''key_bytes'',case when backend_key is null then null else octet_length(backend_key)end,''replay_ttl_seconds'',replay_ttl_seconds,''session_ttl_seconds'',session_ttl_seconds)from eps.review_gateway_config where id'into config;
 end if;
 perform set_config('eps.m07_readback.prior_state',jsonb_build_object('tables',tables,'config',config)::text,true);
end$m06_state$;

do $m07_state$declare settings jsonb;resources jsonb;begin
 if to_regclass('eps.app_settings')is not null then execute 'select jsonb_build_object(''count'',count(*),''settings'',jsonb_agg(jsonb_build_object(''template_version'',template_version,''default_timezone'',default_timezone,''default_review_expiry_days'',default_review_expiry_days,''row_version'',row_version,''identity_present'',resource_id is not null)order by singleton))from eps.app_settings'into settings;end if;
 if to_regclass('eps.mcp_oauth_resources')is not null then execute 'select jsonb_build_object(''count'',count(*),''enabled_count'',count(*)filter(where enabled))from eps.mcp_oauth_resources'into resources;end if;
 perform set_config('eps.m07_readback.new_state',jsonb_build_object('prior',current_setting('eps.m07_readback.prior_state')::jsonb,'app_settings',settings,'mcp_oauth_resources',resources)::text,true);
end$m07_state$;

